3	// Helper function to compare two arrays
4	export function areArraysEqual(arr1?: Array<any>, arr2?: Array<any>): boolean {
5	  if (!arr1 && !arr2) return true;
6	  if (!arr1 || !arr2) return false;
7	  if (arr1.length !== arr2.length) return false;
8	  for (let i = 0; i < arr1.length; i++) {
9	    if (arr1[i] !== arr2[i]) return false;
10	  }
11	  return true;
12	}
13	
14	// Helper function to compare two objects deeply
15	function areObjectsEqual(obj1: any, obj2: any): boolean {
16	  if (obj1 === obj2) return true;
17	  if (typeof obj1 !== typeof obj2) return false;
18	  if (typeof obj1 !== "object" || obj1 === null || obj2 === null) return false;
19	
20	  const keys1 = Object.keys(obj1);
21	  const keys2 = Object.keys(obj2);
22	  if (keys1.length !== keys2.length) return false;
23	
24	  for (const key of keys1) {
25	    if (!keys2.includes(key) || !areObjectsEqual(obj1[key], obj2[key]))
26	      return false;
27	  }
28	  return true;
29	}
30	
31	// Function to compare two ModelRecord instances
32	export function areModelRecordsEqual(
33	  record1: ModelRecord,
34	  record2: ModelRecord,
35	): boolean {
36	  // Compare primitive fields
37	  if (
38	    record1.model !== record2.model ||
39	    record1.model_id !== record2.model_id ||
40	    record1.model_lib !== record2.model_lib ||
41	    record1.vram_required_MB !== record2.vram_required_MB ||
42	    record1.low_resource_required !== record2.low_resource_required ||
43	    record1.buffer_size_required_bytes !== record2.buffer_size_required_bytes
44	  ) {
45	    return false;
46	  }
47	
48	  // Compare required_features arrays
49	  if (
50	    (record1.required_features && !record2.required_features) ||
51	    (!record1.required_features && record2.required_features)
52	  ) {
53	    return false;
54	  }
55	
56	  if (record1.required_features && record2.required_features) {
57	    if (record1.required_features.length !== record2.required_features.length) {
58	      return false;
59	    }
60	
61	    for (let i = 0; i < record1.required_features.length; i++) {
62	      if (record1.required_features[i] !== record2.required_features[i]) {
63	        return false;
64	      }
65	    }
66	  }
67	
68	  return true;
69	}
70	
71	export function areAppConfigsEqual(
72	  config1?: AppConfig,
73	  config2?: AppConfig,
74	): boolean {
75	  if (config1 === undefined || config2 === undefined) {
76	    return config1 === config2;
77	  }
78	
79	  // Check if both configurations have the same cache backend
80	  if (getCacheBackend(config1) !== getCacheBackend(config2)) {
81	    return false;
82	  }
83	  if (
84	    getCacheBackend(config1) === "opfs" &&
85	    (config1.opfsAccessMode ?? "async") !== (config2.opfsAccessMode ?? "async")
86	  ) {
87	    return false;
88	  }
89	
90	  // Check if both configurations have the same number of model records
91	  if (config1.model_list.length !== config2.model_list.length) {
92	    return false;
93	  }
94	
95	  // Compare each ModelRecord in the model_list
96	  for (let i = 0; i < config1.model_list.length; i++) {
97	    if (!areModelRecordsEqual(config1.model_list[i], config2.model_list[i])) {
98	      return false;
99	    }
100	  }
101	
102	  // If all checks passed, the configurations are equal
103	  return true;
104	}
105	
106	export function areChatOptionsEqual(
107	  options1?: ChatOptions,
108	  options2?: ChatOptions,
109	): boolean {
110	  if (options1 === undefined || options2 === undefined) {
111	    return options1 === options2;
112	  }
113	  // Compare each property of ChatOptions (which are Partial<ChatConfig>)
114	  if (!areArraysEqual(options1.tokenizer_files, options2.tokenizer_files))
115	    return false;
116	  if (!areObjectsEqual(options1.conv_config, options2.conv_config))
117	    return false;
118	  if (options1.conv_template !== options2.conv_template) return false;
119	  if (options1.repetition_penalty !== options2.repetition_penalty) return false;
120	  if (options1.frequency_penalty !== options2.frequency_penalty) return false;
121	  if (options1.presence_penalty !== options2.presence_penalty) return false;
122	  if (options1.top_p !== options2.top_p) return false;
123	  if (options1.temperature !== options2.temperature) return false;
124	  if (options1.bos_token_id !== options2.bos_token_id) return false;
125	
126	  // If all checks passed, the options are equal
127	  return true;
128	}
129	
130	export function areChatOptionsListEqual(
131	  options1?: ChatOptions[],
132	  options2?: ChatOptions[],
133	): boolean {
134	  if (options1 && options2) {
135	    // Both defined, need to compare
136	    if (options1.length !== options2.length) {
137	      return false;
138	    } else {
139	      for (let i = 0; i < options1.length; i++) {
140	        if (!areChatOptionsEqual(options1[i], options2[i])) {
141	          return false;
142	        }
143	      }
144	      return true;
145	    }
146	  } else if (!options1 && !options2) {
147	    // Both undefined, equal
148	    return true;
149	  } else {
150	    // One defined, other not
151	    return false;
