20	/**
21	 * Based on `p_prob` of size (vocabSize,) which becomes a distribution after calling
22	 * `applySoftmaxWithTemperature()`, sample `top_logprobs` top-probable tokens.
23	 *
24	 * @param num_top_probs: `top_logprobs` from ChatCompletionRequest
25	 * @param p_prob: `logitsOnCPUArray`, being a distribution after `applySoftmaxWithTemperature()`.
26	 *
27	 * Followed implementation of `ComputeTopProbsImpl()` from [https://github.com/mlc-ai/mlc-llm/blob/
28	 * 5b8c529e9704abd09b0432da6dcb4b013fdf43b1/cpp/serve/sampler/cpu_sampler.cc].
29	 *
30	 * @returns Arrays of (tokenID, prob) pairs, ranked from highest prob to least.
31	 */
32	export function getTopProbs(
33	  num_top_probs: number,
34	  p_prob: Float32Array,
35	): Array<[number, number]> {
36	  if (num_top_probs == 0) return [];
37	  // Initialize to dummy values
38	  const top_probs: Array<[number, number]> = [];
39	  const ndata = p_prob.length;
40	  for (let i = 0; i < num_top_probs; i++) {
41	    top_probs.push([-1, -1.0]);
42	  }
43	
44	  let sum_prob = 0.0;
45	  // Selection argsort.
46	  for (let p = 0; p < ndata; p++) {
47	    let i = num_top_probs - 1;
48	    for (; i >= 0; --i) {
49	      if (p_prob[p] > top_probs[i][1]) {
50	        if (i !== num_top_probs - 1) {
51	          top_probs[i + 1] = top_probs[i];
52	        }
53	      } else {
54	        break;
55	      }
56	    }
57	    if (i !== num_top_probs - 1) {
58	      top_probs[i + 1] = [p, p_prob[p]];
59	    }
60	
61	    // Early exit
62	    sum_prob += p_prob[p];
63	    if (1 - sum_prob <= top_probs[num_top_probs - 1][1]) {
64	      break;
65	    }
66	  }
67	  return top_probs;
68	}
