258	/**
259	 * TODO: Consider if this is the best strategy (though aligned with mlc-llm). We currently greedily
260	 * try to fill up prefillChunkSize. Consider the example with 2048 prefill chunk size:
261	 * const inputData = [
262	    image1,  // 1921
263	    rangeArr(0, 2048),
264	    image2,
265	  ];
266	 * Current approach results in chunks: 
267	   [image1, rangeArr(0, 127)],
268	   [rangeArr(127, 2048)],
269	   [image2],
270	 * This means 4 embedding kernels and 3 prefill kernels.
271	 * While the optimal chunking may be:
272	   [image1],
273	   [rangeArr(0, 2048)],
274	   [image2],
275	 * This results in 3 embedding kernels and 3 prefill kernels.
276	 * However, greedy strategy is more intuitive and probably more generalizable.
277	 */
