279	/**
280	 * Chunk the inputData such that each chunk's total input length is smaller than prefill
281	 * chunk size.
282	 * @returns [the data chunks, the input length of each chunk]
283	 * @note precondition: if inputData has image in it, then prefillChunkSize >= imageEmbedSize.
284	 */
285	export function getChunkedPrefillInputData(
286	  inputData: Array<Array<number> | ImageURL>,
287	  prefillChunkSize: number,
288	  getImageEmbedSize: (image: ImageURL) => number,
289	): [Array<Array<number> | ImageURL>[], Array<number>] {
290	  const chunks: Array<Array<number> | ImageURL>[] = [];
291	  const chunkLens: Array<number> = [];
292	  let curChunk: Array<Array<number> | ImageURL> = [];
293	  let curChunkLen = 0;
294	  for (let i = 0; i < inputData.length; i++) {
295	    let curData: Array<number> | ImageURL = inputData[i];
296	    const curDataLen = Array.isArray(curData)
297	      ? curData.length
298	      : getImageEmbedSize(curData);
299	    if (!Array.isArray(curData) && curDataLen > prefillChunkSize) {
300	      throw new PrefillChunkSizeSmallerThanImageError(
301	        prefillChunkSize,
302	        curDataLen,
303	      );
304	    }
305	    // 1. curData can fit into this chunk
306	    if (curChunkLen + curDataLen <= prefillChunkSize) {
307	      curChunk.push(curData);
308	      curChunkLen += curDataLen;
309	      if (curChunkLen === prefillChunkSize) {
310	        chunks.push([...curChunk]);
311	        chunkLens.push(curChunkLen);
312	        curChunk = [];
313	        curChunkLen = 0;
314	      }
315	      continue;
316	    }
317	
318	    // 2. Otherwise, depends on whether it is token data or image data
319	    if (Array.isArray(curData)) {
320	      // 2.1. Token data, which itself needs to be chunked. Keep
321	      // chunking and finalizing until finished
322	      while (curData.length > 0) {
323	        const curDataToChunkLen = Math.min(
324	          curData.length,
325	          prefillChunkSize - curChunkLen,
326	        );
327	        curChunk.push(curData.slice(0, curDataToChunkLen));
328	        curChunkLen += curDataToChunkLen;
329	        curData = curData.slice(curDataToChunkLen);
330	        if (curChunkLen === prefillChunkSize) {
331	          // curChunk is now full, so finalize to chunks
332	          chunks.push([...curChunk]);
333	          chunkLens.push(curChunkLen);
334	          curChunk = [];
335	          curChunkLen = 0;
336	        }
337	      }
338	    } else {
339	      // 2.2. Image data, which itself cannot be chunked, so cannot fit in current chunk.
340	      // 2.2.1. Finalize curChunk
341	      if (curChunk.length === 0) {
342	        throw new Error(
343	          "InternalError: do not expect curChunk to be empty when an image does not fit.",
344	        );
345	      }
346	      chunks.push([...curChunk]);
347	      chunkLens.push(curChunkLen);
348	      // 2.2.2. Then push image to the new chunk
349	      curChunk = [curData];
350	      curChunkLen = curDataLen;
351	      if (curChunkLen === prefillChunkSize) {
352	        chunks.push([...curChunk]);
353	        chunkLens.push(curChunkLen);
354	        curChunk = [];
355	        curChunkLen = 0;
356	      }
357	    }
358	  }
359	  // Last chunk
360	  if (curChunk.length > 0) {
361	    chunks.push([...curChunk]);
362	    chunkLens.push(curChunkLen);
363	  }
364	
365	  return [chunks, chunkLens];
366	}
