368	type Cont = () => void;
369	
370	/**
371	 * A lock implemented using Promise.
372	 *
373	 * Referred to:
374	 * - https://jackpordi.com/posts/locks-in-js-because-why-not
375	 * - https://www.linkedin.com/pulse/asynchronous-locking-using-promises-javascript-abdul-ahad-o7smf/
376	 */
377	export class CustomLock {
378	  private acquired = false;
379	  private readonly queue: Cont[] = [];
380	
381	  public async acquire(): Promise<void> {
382	    if (!this.acquired) {
383	      // If lock is free, directly return
384	      this.acquired = true;
385	    } else {
386	      // Otherwise, push the request to the queue, and
387	      // a future release() will resolve it
388	      return new Promise<void>((resolve) => {
389	        this.queue.push(resolve);
390	      });
391	    }
392	  }
393	
394	  public async release(): Promise<void> {
395	    if (!this.acquired) {
396	      throw Error("InternalError: expect lock is acquired upon release()");
397	    }
398	    if (this.queue.length === 0) {
399	      // No one is waiting for the lock, so we free it
400	      this.acquired = false;
401	      return;
402	    }
403	
404	    // Otherwise, hand the execution to the next in queue, and
405	    // the lock is still acquired
406	    const cont = this.queue.shift();
407	    return new Promise((res: Cont) => {
408	      cont!();
409	      res();
410	    });
411	  }
412	}
413	
414	// Image related
415	type ImageURL = ChatCompletionContentPartImage.ImageURL;
416	
417	/**
418	 * Given a url, get the image data. The url can either start with `http` or `data:image`.
419	 */
420	export async function getImageDataFromURL(url: string): Promise<ImageData> {
421	  const response = await fetch(url, { mode: "cors" });
422	  const img = await createImageBitmap(await response.blob());
423	  const canvas = new OffscreenCanvas(img.width, img.height);
424	  const ctx = canvas.getContext("2d");
425	  if (!ctx) {
426	    throw new Error("Could not get 2d context");
427	  }
428	  ctx.drawImage(img, 0, 0);
429	
430	  const imageData = ctx.getImageData(0, 0, img.width, img.height);
431	  return imageData;
432	}
433	
434	/**
435	 * Given an ImageData, return the RGB array in Uint8ClampedArray. Note the ImageData.data
436	 * is RGBA, so we skip every fourth element of the data. The order goes by rows from the
437	 * top-left pixel to the bottom-right, in RGB order.
438	 */
439	export function getRGBArrayFromImageData(
440	  imageData: ImageData,
441	): Uint8ClampedArray {
442	  const newData = new Uint8ClampedArray(imageData.width * imageData.height * 3);
443	  for (let i = 0, offset = 0; i < imageData.data.length; i += 4) {
444	    newData[offset++] = imageData.data[i];
445	    newData[offset++] = imageData.data[i + 1];
446	    newData[offset++] = imageData.data[i + 2];
447	  }
448	  return newData;
449	}
